11. function nowCST() {
12.   return new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Shanghai" }));
13. }
14. 
15. function todayStrCST() {
16.   const d = nowCST();
17.   return d.getFullYear() + "-" +
18.     String(d.getMonth()+1).padStart(2,"0") + "-" +
19.     String(d.getDate()).padStart(2,"0");
20. }
