22. function fmtTime(isoStr) {
23.   if (!isoStr) return "";
24.   return new Date(isoStr).toLocaleString("zh-CN", {
25.     timeZone: "Asia/Shanghai", hour12: false
26.   });
27. }
28. 
29. function fmtTimeShort(isoStr) {
30.   if (!isoStr) return "";
31.   return new Date(isoStr).toLocaleTimeString("zh-CN", {
32.     timeZone: "Asia/Shanghai", hour12: false, hour: "2-digit", minute: "2-digit"
33.   });
34. }
