36. async function apiFetch(path, opts = {}) {
37.   const headers = { "Content-Type": "application/json", ...(opts.headers || {}) };
38.   const res = await fetch(API + path, { ...opts, headers });
39.   if (res.status === 204) return null;
40.   const data = await res.json();
41.   if (!res.ok) throw new Error(data.detail || "请求失败");
42.   return data;
43. }
