47. /**
48.  * Returns { startMs, endMs } for the currently selected time period,
49.  * or null if time/duration is not fully specified yet.
50.  */
51. function getSelectedWindow() {
52.   if (!selectedDuration) return null;
53. 
54.   const startType = document.querySelector("input[name=\"start-type\"]:checked");
55.   if (!startType) return null;
56. 
57.   let startMs;
58.   if (startType.value === "now") {
59.     startMs = nowCST().getTime();
60.   } else {
61.     const h = document.getElementById("form-start-hour").value;
62.     const m = document.getElementById("form-start-minute").value;
63.     if (h === "" || m === "") return null;
64.     const dateStr = todayStrCST() + "T" + h.padStart(2,"0") + ":" + m.padStart(2,"0") + ":00+08:00";
65.     startMs = new Date(dateStr).getTime();
66.     if (isNaN(startMs)) return null;
67.   }
68. 
69.   return { startMs, endMs: startMs + selectedDuration * 3600 * 1000 };
70. }
