72. /**
73.  * Check if a GPU has any reservation conflicting with [startMs, endMs].
74.  * Returns the conflicting slot object, or null if free.
75.  */
76. function findConflict(gpu, startMs, endMs) {
77.   for (const slot of (gpu.today_schedule || [])) {
78.     const s = new Date(slot.start_time).getTime();
79.     const e = new Date(slot.end_time).getTime();
80.     if (s < endMs && e > startMs) return slot;
81.   }
82.   return null;
83. }
