87. async function loadServers() {
88.   try {
89.     serversData = await apiFetch("/servers");
90.     renderServersGrid();
91.     populateServerSelect();
92.     // Re-render GPU checkboxes if a server is already selected
93.     const sel = document.getElementById("form-server");
94.     if (sel.value) refreshGpuCheckboxes();
95.   } catch (e) {
96.     document.getElementById("servers-grid").innerHTML =
97.       "<p class=\"text-danger\">\u52a0\u8f7d\u5931\u8d25: " + e.message + "</p>";
98.   }
99. }
