101. function renderServersGrid() {
102.   const grid = document.getElementById("servers-grid");
103.   if (!serversData.length) {
104.     grid.innerHTML = "<p class=\"text-muted\">\u6682\u65e0\u670d\u52a1\u5668\u6570\u636e\uff0c\u8bf7\u8054\u7cfb\u7ba1\u7406\u5458\u6dfb\u52a0\u670d\u52a1\u5668\u3002</p>";
105.     return;
106.   }
107. 
108.   grid.innerHTML = serversData.map(server => {
109.     const gpuChips = server.gpus.map(gpu => {
110.       const isBusy = gpu.status === "occupied";
111.       const upcoming = (gpu.today_schedule || []).filter(s => !s.is_current && s.is_future);
112.       let statusHtml = isBusy
113.         ? "<span class=\"gpu-chip-status busy\"><span class=\"status-dot red\"></span>" +
114.           gpu.current_user + " \u2192 " + fmtTimeShort(gpu.current_end) + "</span>"
115.         : "<span class=\"gpu-chip-status free\"><span class=\"status-dot green\"></span>\u7a7a\u95f2</span>";
116.       const upcomingHtml = upcoming.slice(0,2).map(u =>
117.         "<div class=\"gpu-chip-upcoming\">\u23F3 " + u.username + " " +
118.         fmtTimeShort(u.start_time) + "\u2013" + fmtTimeShort(u.end_time) + "</div>"
119.       ).join("");
120.       const cls = isBusy ? "occupied" : (upcoming.length ? "upcoming" : "available");
121.       return "<div class=\"gpu-chip " + cls + "\">" +
122.         "<span class=\"gpu-chip-id\">GPU " + gpu.device_id + "</span>" +
123.         "<span class=\"gpu-chip-model\">" + gpu.model + "</span>" +
124.         statusHtml + upcomingHtml + "</div>";
125.     }).join("");
126. 
127.     return "<div class=\"server-card\">" +
128.       "<div class=\"server-header\"><div>" +
129.       "<div class=\"server-name\">" + server.name + "</div>" +
130.       "<div class=\"server-host\">" + server.host + "</div>" +
131.       "</div></div>" +
132.       "<div class=\"gpu-chips\">" + (gpuChips || "<span class=\"text-muted\">\u65e0 GPU</span>") + "</div>" +
133.       "</div>";
134.   }).join("");
135. }
