174. /**
175.  * Re-render GPU checkboxes based on current server + time window.
176.  * Removes any previously selected GPUs that are now conflicted.
177.  */
178. function refreshGpuCheckboxes() {
179.   const serverId = document.getElementById("form-server").value;
180.   const container = document.getElementById("gpu-checkboxes");
181. 
182.   if (!serverId) {
183.     container.innerHTML = "<span class=\"text-muted\" style=\"font-size:.85rem\">\u8bf7\u5148\u9009\u62e9\u670d\u52a1\u5668\u548c\u65f6\u95f4\u6bb5</span>";
184.     return;
185.   }
186.   const server = serversData.find(s => s.id === serverId);
187.   if (!server || !server.gpus.length) {
188.     container.innerHTML = "<span class=\"text-muted\">\u8be5\u670d\u52a1\u5668\u6682\u65e0 GPU</span>";
189.     return;
190.   }
191. 
192.   const win = getSelectedWindow();
193. 
194.   // Deselect any GPU that is now conflicted
195.   if (win) {
196.     selectedGpuIds = selectedGpuIds.filter(id => {
197.       const gpu = server.gpus.find(g => g.device_id === id);
198.       return gpu && !findConflict(gpu, win.startMs, win.endMs);
199.     });
200.   }
201. 
202.   container.innerHTML = server.gpus.map(gpu => {
203.     let disabled = false;
204.     let hint = "";
205. 
206.     if (win) {
207.       const conflict = findConflict(gpu, win.startMs, win.endMs);
208.       if (conflict) {
209.         disabled = true;
210.         hint = " (" + conflict.username + " " +
211.           fmtTimeShort(conflict.start_time) + "\u2013" + fmtTimeShort(conflict.end_time) + " \u51b2\u7a81)";
212.       }
213.     }
214. 
215.     const isSelected = selectedGpuIds.includes(gpu.device_id);
216.     const labelText = "GPU " + gpu.device_id + "\u00a0" + gpu.model + hint;
217.     const cls = "gpu-checkbox-item" + (disabled ? " disabled" : "") + (isSelected ? " selected" : "");
218. 
219.     return "<div class=\"" + cls + "\"" +
220.       (disabled ? "" : " onclick=\"toggleGpu(" + gpu.device_id + ", this)\"") + ">" +
221.       "<input type=\"checkbox\" value=\"" + gpu.device_id + "\"" +
222.       (disabled ? " disabled" : "") + (isSelected ? " checked" : "") +
223.       " style=\"pointer-events:none\" />" +
224.       "<span>" + labelText + "</span></div>";
225.   }).join("");
226. 
227.   // Show hint if no time window set yet
228.   if (!win) {
229.     const hint = document.createElement("div");
230.     hint.style.cssText = "font-size:.82rem;color:var(--muted);margin-top:6px;width:100%";
231.     hint.textContent = "\u5c1a\u672a\u9009\u62e9\u65f6\u95f4\u6bb5\uff0c\u5c55\u793a\u5f53\u524d\u5360\u7528\u72b6\u6001\uff1b\u9009\u597d\u65f6\u95f4\u6bb5\u540e\u5c06\u81ea\u52a8\u6807\u6ce8\u51b2\u7a81";
232.     container.appendChild(hint);
233.   }
234. }
