236. function toggleGpu(deviceId, el) {
237.   if (el.classList.contains("disabled")) return;
238.   const cb = el.querySelector("input");
239.   const idx = selectedGpuIds.indexOf(deviceId);
240.   if (idx === -1) {
241.     selectedGpuIds.push(deviceId);
242.     el.classList.add("selected");
243.     cb.checked = true;
244.   } else {
245.     selectedGpuIds.splice(idx, 1);
246.     el.classList.remove("selected");
247.     cb.checked = false;
248.   }
249. }
