253. async function submitReservation() {
254.   const errEl = document.getElementById("form-error");
255.   const okEl  = document.getElementById("form-success");
256.   errEl.textContent = "";
257.   okEl.textContent  = "";
258. 
259.   const username = document.getElementById("form-username").value.trim();
260.   const serverId  = document.getElementById("form-server").value;
261. 
262.   if (!username)              { errEl.textContent = "\u8bf7\u586b\u5199\u7528\u6237\u540d"; return; }
263.   if (!serverId)              { errEl.textContent = "\u8bf7\u9009\u62e9\u670d\u52a1\u5668"; return; }
264.   if (!selectedDuration)      { errEl.textContent = "\u8bf7\u9009\u62e9\u4f7f\u7528\u65f6\u957f"; return; }
265.   if (!selectedGpuIds.length) { errEl.textContent = "\u8bf7\u81f3\u5c11\u9009\u62e9\u4e00\u5757 GPU"; return; }
266. 
267.   let startTimeISO = null;
268.   const startType = document.querySelector("input[name=\"start-type\"]:checked").value;
269.   if (startType === "custom") {
270.     const h = document.getElementById("form-start-hour").value;
271.     const m = document.getElementById("form-start-minute").value;
272.     if (h === "" || m === "") { errEl.textContent = "\u8bf7\u9009\u62e9\u5f00\u59cb\u65f6\u95f4"; return; }
273.     startTimeISO = todayStrCST() + "T" + h.padStart(2,"0") + ":" + m.padStart(2,"0") + ":00+08:00";
274.   }
275. 
276.   try {
277.     await apiFetch("/reservations", {
278.       method: "POST",
279.       body: JSON.stringify({
280.         username, server_id: serverId,
281.         gpu_ids: selectedGpuIds,
282.         start_time: startTimeISO,
283.         duration_hours: selectedDuration,
284.       }),
285.     });
286.     okEl.textContent = "\u2713 \u9884\u7ea6\u6210\u529f\uff01";
287.     selectedGpuIds = [];
288.     selectedDuration = 0;
289.     document.querySelectorAll(".duration-btn").forEach(b => b.classList.remove("selected"));
290.     await loadServers();
291.     document.getElementById("query-username").value = username;
292.     loadMyReservations();
293.   } catch (e) {
294.     errEl.textContent = e.message;
295.   }
296. }
