312.     }
313.     container.innerHTML = list.map(r =>
314.       "<div class=\"reservation-item\">" +
315.       "<div class=\"reservation-info\">" +
316.       "<span class=\"reservation-server\">" + (r.server_name || r.server_id) +
317.         " \u2014 GPU " + r.gpu_ids.join(", ") + "</span>" +
318.       "<span class=\"reservation-detail\">\u9884\u7ea6\u4eba: " + r.username + "</span>" +
319.       "<span class=\"reservation-time\">" + fmtTime(r.start_time) + " \u2192 " + fmtTime(r.end_time) + "</span>" +
320.       "</div>" +
321.       "<div style=\"display:flex;align-items:center;gap:8px\">" +
322.       "<span class=\"status-badge active\">\u8fdb\u884c\u4e2d / \u5f85\u5f00\u59cb</span>" +
323. 
324.       "</div></div>"
325.     ).join("");
326.   } catch (e) {
327.     container.innerHTML = "<p class=\"text-danger\">\u67e5\u8be2\u5931\u8d25: " + e.message + "</p>";
328.   }
329. }
