333. function initTimeSelects() {
334.   const hourEl = document.getElementById("form-start-hour");
335.   const minEl  = document.getElementById("form-start-minute");
336. 
337.   // Build options only once
338.   if (!hourEl.options.length) {
339.     for (let h = 0; h < 24; h++) {
340.       hourEl.add(new Option(String(h).padStart(2,"0"), String(h)));
341.     }
342.   }
343.   if (!minEl.options.length) {
344.     for (let m = 0; m < 60; m += 5) {
345.       minEl.add(new Option(String(m).padStart(2,"0"), String(m)));
346.     }
347.   }
348. 
349.   // Pre-fill with next 5-minute slot if not yet set
350.   if (hourEl.value === "") {
351.     const d = nowCST();
352.     d.setMinutes(Math.ceil((d.getMinutes() + 1) / 5) * 5, 0, 0);
353.     const hr  = d.getHours();
354.     const mn  = Math.floor(d.getMinutes() / 5) * 5; // snap to 5-min grid
355.     hourEl.value = String(hr);
356.     minEl.value  = String(mn);
357.   }
358. }
